pc = [t(110, 34, 'шанс хоча б раз зустріти 6+ мінусів поспіль', 'muted', 16, 'start', 600)]
for v in (0, 25, 50, 75, 100):
    pc.append(line(100, YY(v), 650, YY(v), GRID, 1)); pc.append(t(90, YY(v) + 6, f'{v}%', 'muted', 16, 'end', 600))
for i, n in enumerate(ns):
    pc.append(t(XX(i), 348, n, 'muted', 16, 'middle', 600))
pc.append(t(380, 374, 'кількість угод', 'muted', 16, 'middle', 600))
for data, col in ((p50, 'rose'), (p60, 'amber')):
    P = [(XX(i), YY(v)) for i, v in enumerate(data)]
    pc.append(poly(P, col, 3)); pc += [dot(x, y, col) for x, y in P]
pc.append(t(XX(2) + 14, YY(54.6) + 26, '55%', 'rose', 17))
pc.append(t(XX(2) + 12, YY(21.3) + 26, '21%', 'amber', 17))
